// Backend ile iletişim kuracak basit servis
import axios from 'axios';

// Backend API URL'i
const BACKEND_API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';

// Aura türlerini tanımla
export const auraTypes = ['yaratıcı', 'ruhsal', 'kişisel', 'kariyer'];

// Quiz cevaplarını analiz edip dominant aura tipini belirleyen fonksiyon
export const determineDynamicAuraType = (answers: { [key: number]: string }): string => {
  // Cevapların sayılarını say
  const answerCounts = { a: 0, b: 0, c: 0, d: 0 };

  // Her cevabı değerlendir
  Object.values(answers).forEach(answer => {
    if (answer === 'a') answerCounts.a++;
    else if (answer === 'b') answerCounts.b++;
    else if (answer === 'c') answerCounts.c++;
    else if (answer === 'd') answerCounts.d++;
  });

  // En çok verilen cevabı bul
  let dominant = 'a';
  let maxCount = answerCounts.a;

  for (const [answer, count] of Object.entries(answerCounts)) {
    if (count > maxCount) {
      dominant = answer;
      maxCount = count;
    }
  }

  // Dominant cevaba göre aura tipini belirle
  switch (dominant) {
    case 'a': return 'analitik';
    case 'b': return 'yaratıcı';
    case 'c': return 'empatik';
    case 'd': return 'enerjik';
    default: return 'yaratıcı';
  }
};

// Hikaye alma fonksiyonu - backend API'sine istek
export const getAuraStoryFromOpenAI = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<string> => {
  try {
    console.log(`[Frontend] ${auraType} tipi için hikaye isteniyor`);
    
    // Backend API'sine istek gönder
    const response = await axios.post(
      `${BACKEND_API_URL}/aura/story`,
      {
        auraType,
        username,
        answers
      }
    );
    
    // Cevabı döndür
    return response.data.story;
  } catch (error) {
    console.error('Backend API hatası (hikaye):', error);
    return "Aura hikayeniz şu anda oluşturulamıyor. Lütfen daha sonra tekrar deneyin.";
  }
};

// İçgörüler alma fonksiyonu - backend API'sine istek
export const getAuraInsightsFromOpenAI = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string },
  detailedAnswers?: any
): Promise<{
  strengths: string,
  potential: string,
  thinkingStyle: string,
  auraTitle: string,
  source: 'openai' | 'default'
}> => {
  try {
    console.log(`[Frontend] ${auraType} tipi için içgörüler isteniyor`);
    
    // Backend API'sine istek gönder
    const response = await axios.post(
      `${BACKEND_API_URL}/aura/insights`,
      {
        auraType,
        username,
        answers,
        detailedAnswers
      }
    );
    
    return {
      ...response.data,
      source: response.data.source || 'openai'
    };
  } catch (error) {
    console.error('Backend API hatası (içgörüler):', error);
    
    // Hata durumunda varsayılan değerler döndür
    return {
      strengths: "Güçlü yönleriniz şu anda yüklenemiyor.",
      potential: "Potansiyeliniz şu anda yüklenemiyor.",
      thinkingStyle: "Düşünme stiliniz şu anda yüklenemiyor.",
      auraTitle: `${auraType.charAt(0).toUpperCase() + auraType.slice(1)} Aura`,
      source: 'default'
    };
  }
};

// Birleştirilmiş aura verisi alma fonksiyonu - backend API'sine istek
export const getCombinedAuraDataFromOpenAI = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<{
  story: string,
  strengths: string,
  potential: string,
  thinkingStyle: string,
  auraTitle: string,
  source: 'openai' | 'default',
  fromCache?: boolean
}> => {
  try {
    console.log(`[Frontend] ${auraType} tipi için birleştirilmiş veri isteniyor`);
    
    // Önbellekte kontrolü - anahtar oluşturalım
    const memCacheKey = `inMemory_combined_${auraType}_${username}_${JSON.stringify(answers)}`;
    
    // İstek yapılmadan önce, son 10 dakika içinde aynı istek için önbellekte veri var mı kontrol edelim
    // Uygulama oturumu boyunca geçerli olacak önbellek 
    if (window.auralizeCombinedCache && window.auralizeCombinedCache[memCacheKey]) {
      const cachedItem = window.auralizeCombinedCache[memCacheKey];
      // 10 dakikadan eski değilse önbellekten döndür
      if (Date.now() - cachedItem.timestamp < 10 * 60 * 1000) { // 10 dakika
        console.log(`[Frontend] Önbellekten veri alındı (memory): ${auraType}`);
        console.log('[Frontend] Önbellek verileri:', {
          hasStory: !!cachedItem.data.story,
          hasStrengths: !!cachedItem.data.strengths,
          hasPotential: !!cachedItem.data.potential,
          hasThinkingStyle: !!cachedItem.data.thinkingStyle,
          auraTitle: cachedItem.data.auraTitle,
          önbellekZamanDamgası: new Date(cachedItem.timestamp).toLocaleString(),
          önbellekYaşı: Math.round((Date.now() - cachedItem.timestamp) / 1000 / 60) + ' dakika'
        });
        return {
          ...cachedItem.data,
          fromCache: true // Verinin önbellekten geldiğini belirten bayrak
        };
      }
    }
    
    // Devam eden istek var mı kontrol et
    if (window.auralizeInProgressRequests && memCacheKey in window.auralizeInProgressRequests) {
      console.log(`[Frontend] Aynı istek zaten işlemde, mevcut isteğe katılıyor: ${auraType}`);
      console.log(`[Frontend] İstek anahtar: ${memCacheKey.substring(0, 30)}...`);
      
      // Var olan isteği bekle ve ve fromCache:false ekle, çünkü bu API isteği
      const result = await window.auralizeInProgressRequests[memCacheKey];
      return {
        ...result,
        fromCache: false
      };
    }
    
    // Backend API'sine istek gönder
    console.log(`[Frontend] ${auraType} için API isteği gönderiliyor`);
    
    // İsteği kaydediyoruz
    if (!window.auralizeInProgressRequests) {
      window.auralizeInProgressRequests = {};
    }
    
    // İsteği promise olarak oluştur ve kaydet
    const requestPromise = axios.post(
      `${BACKEND_API_URL}/aura/combined`,
      {
        auraType,
        username,
        answers
      }
    )
    .then(response => {
      // İstek sonuçlandı
      console.log(`[Frontend] Backend'den yanıt alındı (${response.data.source})`, new Date().toLocaleTimeString());
      
      // Sonucu önbelleğe al
      if (!window.auralizeCombinedCache) {
        window.auralizeCombinedCache = {};
      }
      window.auralizeCombinedCache[memCacheKey] = {
        timestamp: Date.now(),
        data: {
          ...response.data,
          source: response.data.source || 'openai'
        }
      };
      
      // İstek tamamlandı, listeden kaldır
      if (window.auralizeInProgressRequests) {
        delete window.auralizeInProgressRequests[memCacheKey];
      }
      
      return {
        ...response.data,
        source: response.data.source || 'openai',
        fromCache: false // API'den gelen yanıt olduğunu belirten bayrak
      };
    })
    .catch(error => {
      // Hata durumunda da isteği listeden kaldır
      if (window.auralizeInProgressRequests) {
        delete window.auralizeInProgressRequests[memCacheKey];
      }
      
      console.error('Backend API hatası (birleştirilmiş):', error);
      
      // Hata durumunda varsayılan değerler döndür
      return {
        story: "Aura hikayeniz şu anda yüklenemiyor.",
        strengths: "Güçlü yönleriniz şu anda yüklenemiyor.",
        potential: "Potansiyeliniz şu anda yüklenemiyor.",
        thinkingStyle: "Düşünme stiliniz şu anda yüklenemiyor.",
        auraTitle: `${auraType.charAt(0).toUpperCase() + auraType.slice(1)} Aura`,
        source: 'default'
      };
    });
    
    // İsteği devam eden istekler listesine ekle
    window.auralizeInProgressRequests[memCacheKey] = requestPromise;
    
    // İsteği başlat ve sonucu döndür
    return await requestPromise;
  } catch (error) {
    console.error('Backend API hatası (birleştirilmiş):', error);
    
    // Hata durumunda varsayılan değerler döndür
    return {
      story: "Aura hikayeniz şu anda yüklenemiyor.",
      strengths: "Güçlü yönleriniz şu anda yüklenemiyor.",
      potential: "Potansiyeliniz şu anda yüklenemiyor.",
      thinkingStyle: "Düşünme stiliniz şu anda yüklenemiyor.",
      auraTitle: `${auraType.charAt(0).toUpperCase() + auraType.slice(1)} Aura`,
      source: 'default'
    };
  }
};

// Import bölümü önüne TypeScript için Window interface extension ekleyelim
declare global {
  interface Window {
    auralizeCombinedCache?: {
      [key: string]: {
        timestamp: number;
        data: any;
      }
    };
    auralizeInProgressRequests?: {
      [key: string]: Promise<any>;
    }
  }
}
